import { GoogleGenerativeAI, HarmBlockThreshold, HarmCategory } from "@google/generative-ai";

class GeminiService {
  private ai: GoogleGenerativeAI;
  private model: string;

  constructor(apiKey: string) {
    this.ai = new GoogleGenerativeAI(apiKey);
    this.model = "gemini-2.5-flash"; // updated model
  }

  async chatWithGemini(userMessage: string) {
    // For text-only input, use the gemini-pro model
    const generationConfig = {
      temperature: 0.9,
      topK: 1,
      topP: 1,
      maxOutputTokens: 2048,
    };

    const safetySettings = [
      {
        category: HarmCategory.HARASSMENT,
        threshold: HarmBlockThreshold.HIGH,
      },
      {
        category: HarmCategory.HATE_SPEECH,
        threshold: HarmBlockThreshold.HIGH,
      },
      {
        category: HarmCategory.SEXUALLY_EXPLICIT,
        threshold: HarmBlockThreshold.HIGH,
      },
      {
        category: HarmCategory.DANGEROUS_CONTENT,
        threshold: HarmBlockThreshold.HIGH,
      },
    ];

    const model = this.ai.getGenerativeModel({ model: this.model, generationConfig, safetySettings });

    const chat = model.startChat({});
    let result = await chat.sendMessage({ message: userMessage });

    return {
      text: result.response.text(),
    };
  }
}

export default new GeminiService(process.env.API_KEY || "");
